"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["11473"],{86081(e){e.exports=JSON.parse('{"id":"F415","slug":"pairs-trade-sizing","name":"Pairs Trade Sizing and Reversion Profit","subject":"Quantitative Finance","section":"Quant","topic":"Statistical arbitrage and pairs trading","level":"Intermediate","aliases":["statistical arbitrage","stat arb","pairs trading","spread trade"],"formula":{"latex":"z=\\\\frac{s-\\\\bar{s}}{\\\\sigma_{s}},\\\\quad \\\\text{Units}=\\\\left\\\\lfloor\\\\frac{K}{P_{Y}+\\\\beta P_{X}}\\\\right\\\\rfloor,\\\\quad \\\\text{Profit}=\\\\text{Units}\\\\times|s-\\\\bar{s}|","also":[],"text":"z-score = (spread - mean spread) / sd of spread; Units of the pair = floor(capital / (price Y + hedge ratio x price X)); Profit if the spread returns to its mean = Units x |spread - mean|"},"symbols":[{"symbol":"s","meaning":"Current spread, Y - beta x X","unit":"money"},{"symbol":"s-bar, sigma_s","meaning":"Mean and standard deviation of the spread","unit":"money"},{"symbol":"beta","meaning":"Hedge ratio: units of X per unit of Y","unit":"number"},{"symbol":"K","meaning":"Capital allocated to gross exposure","unit":"money"}],"when_to_use":"Use it to size a trade once a spread has been identified. When the z-score is large and positive the spread is rich: short Y and buy beta units of X. When it is large and negative, do the reverse. Profit assumes the spread fully reverts, and ignores costs, financing and the chance that the relationship has broken, so it is an upper bound, not a forecast.","worked_example":{"problem":"The spread has a mean of 0.40 and a standard deviation of 0.80 and is now 2.40. The hedge ratio is 1.5, Y trades at 120 and X at 70, and 50,000 of capital is allocated to gross exposure.","inputs":{"s":2.4,"m":0.4,"sd":0.8,"beta":1.5,"py":120,"px":70,"k":50000},"steps":[{"label":"z-score = (s - mean) / sd","working":"(2.4-0.4) / sd","value":"2.50"},{"label":"Gross exposure per unit = price Y + beta x price X","working":"120+1.5 x 70","value":"225.00"},{"label":"Units = floor(capital / gross per unit)","working":null,"value":"222"},{"label":"Profit if the spread returns to the mean = units x |s - mean|","working":null,"value":"444.00"},{"label":"Return on capital","working":"444 / 50000","value":"0.89%"}],"answer":"The z-score is 2.50, so the spread is rich: short Y and buy X. Each unit of the pair uses 225.00 of gross exposure, so 222 units fit in the capital. Reversion to the mean would earn 444.00, or 0.89% of the capital."},"calculator":{"available":true,"inputs":[{"id":"s","label":"Current spread","unit":"","type":"number","default":2.4,"hint":""},{"id":"m","label":"Mean of the spread","unit":"","type":"number","default":0.4,"hint":""},{"id":"sd","label":"Standard deviation of the spread","unit":"","type":"number","default":0.8,"hint":""},{"id":"beta","label":"Hedge ratio","unit":"","type":"number","default":1.5,"hint":""},{"id":"py","label":"Price of Y","unit":"money","type":"number","default":120,"hint":""},{"id":"px","label":"Price of X","unit":"money","type":"number","default":70,"hint":""},{"id":"k","label":"Capital for gross exposure","unit":"money","type":"number","default":50000,"hint":""}],"checks":[{"expr":"sd>0 and beta>0 and py>0 and px>0 and k>0","message":"Enter values above zero."}],"steps":[{"id":"z","label":"z-score = (s - mean) / sd","expr":"(s-m)/sd","format":"num2"},{"id":"gross","label":"Gross exposure per unit = price Y + beta x price X","expr":"py+beta*px","format":"money"},{"id":"units","label":"Units = floor(capital / gross per unit)","expr":"floor(k/gross)","format":"num0"},{"id":"profit","label":"Profit if the spread returns to the mean = units x |s - mean|","expr":"units*abs(s-m)","format":"money"},{"id":"ret","label":"Return on capital","expr":"profit/k","format":"pct2"}],"results":["z","units","profit"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"z":2.5,"gross":225,"units":222,"profit":444,"ret":0.00888}},"finder":{"finds":"How big to make a pairs trade and what reversion would earn","needs":"Spread statistics, hedge ratio, prices, capital"},"related":[{"slug":"cointegration-half-life","name":"Cointegration: Hedge Ratio, Spread Z-Score and Half-Life"},{"slug":"kelly-criterion","name":"Kelly Criterion"},{"slug":"strategy-backtest-metrics","name":"Backtest Performance Metrics"}],"related_ids":["F414","F522","F416"],"group":"Risk and quantitative methods","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><mi>z</mi><mo>=</mo><mfrac><mrow><mi>s</mi><mo>\u2212</mo><mover accent=\\"true\\"><mi>s</mi><mo>\u02C9</mo></mover></mrow><msub><mi>\u03C3</mi><mi>s</mi></msub></mfrac><mo separator=\\"true\\">,</mo><mspace width=\\"1em\\"/><mtext>Units</mtext><mo>=</mo><mrow><mo fence=\\"true\\">\u230A</mo><mfrac><mi>K</mi><mrow><msub><mi>P</mi><mi>Y</mi></msub><mo>+</mo><mi>\u03B2</mi><msub><mi>P</mi><mi>X</mi></msub></mrow></mfrac><mo fence=\\"true\\">\u230B</mo></mrow><mo separator=\\"true\\">,</mo><mspace width=\\"1em\\"/><mtext>Profit</mtext><mo>=</mo><mtext>Units</mtext><mo>\xd7</mo><mi mathvariant=\\"normal\\">\u2223</mi><mi>s</mi><mo>\u2212</mo><mover accent=\\"true\\"><mi>s</mi><mo>\u02C9</mo></mover><mi mathvariant=\\"normal\\">\u2223</mi></mrow><annotation encoding=\\"application/x-tex\\">z=\\\\frac{s-\\\\bar{s}}{\\\\sigma_{s}},\\\\quad \\\\text{Units}=\\\\left\\\\lfloor\\\\frac{K}{P_{Y}+\\\\beta P_{X}}\\\\right\\\\rfloor,\\\\quad \\\\text{Profit}=\\\\text{Units}\\\\times|s-\\\\bar{s}|</annotation></semantics></math></span>","alsoMathml":[],"prev":{"slug":"pe-earnings-yield","name":"P/E Ratio and Earnings Yield"},"next":{"slug":"payback-period","name":"Payback Period"},"lesson":null,"total":522}')}}]);